# The static initialisers and their exit thunks (src/game/core/staticinit, generated by tools/gen_static_init.py, and staticinitmanual)
# against the originals: each generated initialiser (Main: the data table's rows; Lifted: the lifted ones and the two by hand), each exit
# thunk (Exit) and StaticInit_Run over a table of a few entries (Run: the original's 0x67f90d, CRT_initterm(0x727000, 0x72e0e8)).
# Every call they make goes to a recorder through the case's call table at CALLS (driver.cpp kStaticInitCalls: the generated module's
# AddrCalls; the emulator's hooks of the same addresses look the recorder up there), so the log holds the calls in order with their
# arguments; atexit 0x67a7d0 is the cdecl recorder 31, natively through driver.cpp's stub_static_init_atexit (ATEXIT_STUB), which turns
# the C++ exit thunk back into the original's address. Import slots the code calls through hold recorders (a region over the slot). The
# globals each writes (found by a dry run of the original) and reads (its absolute operands) are regions: random bytes, or the exe's.
# A full pass: OPS=Main staticinit.py 6463 5; OPS=Lifted ... 567; OPS=Exit ... 6495 (each item once per round of r.deal).
# usage: staticinit.py [CASES [SEED]] [--wild|--both] [--show N]   (env OPS=Main,Lifted,Exit,Run)
import os
import re
import struct
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'tools'))
from fncmp import GAME_HIGH, GAME_LOW, LOG, STUBS, Bench, Call, _recorder, blob, fill, log_region, recorder, strings  # noqa: E402
import gen_static_init as gsi  # noqa: E402
import x87emu  # noqa: E402

G = gsi.analyse()
CALLS = 0x2c000000          # driver.cpp kStaticInitCalls: 64 (address, target) entries
VBTABLE = CALLS + 0x800     # (Exit 0x540880's vbtable)
# The initialisers run at the CRT's start-up control word: 0x27f (PC53; _FPinit 0x67a5f0's _setdefaultprecision 0x6804d0 sets PC53
# before _initterm); the exit thunks at the game's, 0x7f.
CW_START = 0x27f
ATEXIT_STUB = STUBS + 0xe0  # driver.cpp stub_static_init_atexit
K_ATEXIT = 31               # (the cdecl recorder of one argument it ends in)
TABLE, TABLE_END = gsi.TABLE, gsi.TABLE_END
MAIN = sorted(a for a, k in G.kinds.items() if k == 'main')
LIFTED = sorted(a for a, k in G.kinds.items() if k in ('lifted', 'manual'))
EXITS = sorted(t for t in G.thunks if G.thunks[t][0] == 'template' or t in G.lifted)
OTHER = sorted(a for a, k in G.kinds.items() if k in ('hooked', 'clib'))   # (Run: table entries the runner calls by address)
GENERATED = set(MAIN) | set(LIFTED)
OPS = os.environ.get('OPS', 'Main,Lifted,Exit,Run').split(',')
IMAGE = x87emu.exe_sections()


def image(a, n):
    for base, data in IMAGE:
        if base <= a and a + n <= base + len(data):
            return bytes(data[a - base:a + n - base])
    return bytes(n)


def ranges():
    spans = []
    for a in sorted(GENERATED | set(EXITS)):
        body = G.bodies[a]
        spans.append((body[0][0], body[-1][0] + 1))
    spans += [(0x67f90d, 0x67f920), (0x67fa40, 0x67fa60), (gsi.EMPTY, gsi.EMPTY + 1)]
    out = []
    for lo, hi in sorted(spans):
        if out and lo <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], hi))
        else:
            out.append((lo, hi))
    return out


# the calls of the two by hand (staticinitmanual.cpp), which the generator does not lift
G.callees.setdefault(0x412b90, [(gsi.ATEXIT, 'C', 1)])
G.callees.setdefault(0x583540, [(0x55e470, 'T', 0), (('import', 0x6fd148), 'S', 1), (0x55e570, 'T', 1)])
# the arguments that point into the initialiser's frame, whose address differs between the sides: (initialiser, callee) -> (argument, mask):
# the dwords it points to that the mask selects hashed (blob), or (mask None) logged as 0 (47f2f0: an empty object's uninitialised byte)
# (blob() takes one argument a slot: 4bbb20's first, the size 0x280 x 0xf0 it stores from immediates, is logged as 0)
STACK_ARGS = {(0x47f2f0, 0x47f910): [(0, None)], (0x4bbb20, 0x5fa6a0): [(0, None), (1, 0x3f)]}
CALLEES = {t for cs in G.callees.values() for t, kind, n in cs if not isinstance(t, tuple) and kind != 'G' and t != gsi.ATEXIT} | set(OTHER)


def _lookup(address):
    """The emulator's hook of a callee: the recorder the case's call table gives it (a fault when it gives none)."""
    def hook(e):
        for i in range(64):
            a, t = struct.unpack('<2I', e.read(CALLS + 8 * i, 8))
            if a == address:
                return B.emu.hooks[t](e)
        raise x87emu.MemFault('%x not in the call table' % address)
    return hook


HOOKS = {a: _lookup(a) for a in CALLEES}
HOOKS[gsi.ATEXIT] = _recorder(K_ATEXIT, 1, cdecl=True)
B = Bench(ranges(), hooks=HOOKS)


def closure(addresses):
    """The functions the case runs: the addresses and the generated initialisers they tail-jump to."""
    out, todo = [], list(addresses)
    while todo:
        a = todo.pop()
        if a in out or a not in G.bodies:
            continue
        out.append(a)
        todo += [t for t, kind, _ in G.callees.get(a, []) if kind == 'G']
    return out


def table(functions, log, regions, extra=()):
    """The call table of the functions' callees (and extra: (address, kind, n)), each its own k; import slots as regions holding recorders."""
    entries, k = [(gsi.ATEXIT, ATEXIT_STUB)], 0
    seen = set()
    for f, (t, kind, n) in [(f, c) for f in functions for c in G.callees.get(f, [])] + [(None, c) for c in extra]:
        if kind == 'G' or t == gsi.ATEXIT or t in seen:
            continue
        seen.add(t)
        rec = recorder(k, n) if kind == 'T' else recorder(k, n, cdecl=True) if kind == 'C' else recorder(k, n, com=True)
        if isinstance(t, tuple):   # (an import slot: called through, read live)
            regions[t[1]] = struct.pack('<I', rec)
            if G.import_names.get(t[1]) == 'GlobalMemoryStatus':   # (its MEMORYSTATUS on the caller's stack: logged as 0, filled)
                strings(log, k, 0, out=1)
                fill(log, k, 0, bytes(range(0x20, 0x40)))
        else:
            entries.append((t, rec))
            for arg, mask in STACK_ARGS.get((f, t), ()):
                strings(log, k, 0, out=1 << arg) if mask is None else blob(log, k, arg, mask)
        k += 1
    assert k < K_ATEXIT and len(entries) <= 64
    return b''.join(struct.pack('<2I', a, t) for a, t in entries) + bytes(8 * (64 - len(entries)))


def operands(f):
    """The absolute memory operands of f's instructions: (address, bytes)."""
    out = []
    for _, ins in G.bodies[f]:
        for m in re.finditer(r'(?:(byte|word|dword|float|double|qword) ptr )?\[0x([0-9a-f]+)\]', ins):
            out.append((int(m.group(2), 16), {'byte': 1, 'word': 2, 'double': 8, 'qword': 8}.get(m.group(1), 4)))
    return out


WRITTEN = {}


def written(f):
    """What the original of f writes in the game's data (a dry run on the exe's bytes), as (address, bytes) runs."""
    if f not in WRITTEN:
        log = log_region()
        regions = {LOG: log}
        regions[CALLS] = table(closure([f]), log, regions)
        fixed = set(regions)
        strict, B.strict = B.strict, False
        try:
            B.original(Call(f, [], regions))
        finally:
            B.strict = strict
        WRITTEN[f] = [(a, 1) for a in B.emu.mem if GAME_LOW <= a < GAME_HIGH and not any(k <= a < k + len(regions[k]) for k in fixed)]
    return WRITTEN[f]


def data(r, functions, regions):
    """The globals the functions read and write, merged into runs: random bytes, or the exe's."""
    spans = sorted({(a + i) for f in functions for a, n in operands(f) + written(f) for i in range(n)
                    if GAME_LOW <= a < GAME_HIGH} - {a + i for a, v in regions.items() for i in range(len(v))})
    runs = []
    for a in spans:
        if runs and a - runs[-1][1] <= 4:
            runs[-1][1] = a + 1
        else:
            runs.append([a, a + 1])
    random = r.random() < 0.5
    for lo, hi in runs:
        regions[lo] = r.bytes(hi - lo) if random else bytearray(image(lo, hi - lo))
    if random:   # (a double operand's random bits can pass the emulator's range (its x87 has a 15-bit exponent): a double of a modest exponent)
        for f in functions:
            for va, ins in G.bodies[f]:
                for m in re.finditer(r'double ptr \[0x([0-9a-f]+)\]', ins):
                    a = int(m.group(1), 16)
                    lo = max(k for k in regions if k <= a)
                    struct.pack_into('<d', regions[lo], a - lo, r.choice([-1, 1]) * r.random() * 2.0 ** r.randrange(-40, 40))


def case(r):
    op = r.deal(OPS)
    log = log_region()
    regions = {LOG: log}
    if op == 'Run':
        slots = bytearray(TABLE_END - TABLE)
        chosen, extra = [], []
        for _ in range(r.choice([1, 2, 3])):
            v = r.choice(MAIN) if r.random() < 0.5 else r.choice(LIFTED) if r.random() < 0.6 else r.choice(OTHER)
            struct.pack_into('<I', slots, 4 * r.randrange(len(slots) // 4), v)
            if v in GENERATED:
                chosen.append(v)
            else:
                extra.append((v, 'C', 0))
        functions = closure(chosen)
        regions[CALLS] = table(functions, log, regions, extra)
        regions[TABLE] = slots
        data(r, functions, regions)
        return Call(0x67f90d, [], regions, ret='c', cw=CW_START)
    f = r.deal(MAIN if op == 'Main' else LIFTED if op == 'Lifted' else EXITS)
    functions = closure([f])
    regions[CALLS] = table(functions, log, regions)
    if f == 0x540880:   # (the object at 0x876420 has a virtual base: its vbtable pointer, as its constructor set it, gives the base's offset)
        off = r.randrange(2, 16) * 4
        regions[VBTABLE] = struct.pack('<2I', 0, off)
        regions[0x876420] = struct.pack('<I', VBTABLE) + r.bytes(off + 4)
    data(r, functions, regions)
    return Call(f, [], regions, ret='c', cw=0x7f if op == 'Exit' else CW_START)


if __name__ == '__main__':
    B.main(case)
